use crate::wasi::clocks::wall_clock;

struct Node;

/// Latest instant whose UTC date still has a four-digit year: 9999-12-31T23:59:59Z.
const MAX_SECONDS: u64 = 253_402_300_799;

/// Convert days since 1970-01-01 to a (year, month, day) civil date (proleptic Gregorian).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let seconds = now.seconds;

        // Clamp so the date always renders as YYYY-MM-DD (exactly 10 chars).
        let clamped = if seconds > MAX_SECONDS { MAX_SECONDS } else { seconds };
        let (y, m, d) = civil_from_days(clamped / 86_400);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo {
            date,
            started: seconds,
        }
    }
}

export!(Node);
